mapper.select:
SELECT ,
    r.created_by, r.updated_by, r.deleted_at
FROM restaurants r JOIN restaurant_categories c ON c.code = r.category_code WHERE r.id = #{id}

SELECT tag FROM (
    SELECT tag, position, ROW_NUMBER() OVER (
        PARTITION BY tag COLLATE utf8mb4_0900_ai_ci ORDER BY position
    ) AS duplicate_order FROM (

            SELECT CONVERT(#{tag} USING utf8mb4) AS tag, #{position} AS position

    ) candidates
) normalized WHERE duplicate_order = 1 ORDER BY position
